/** Frame's props. @since 1.2 */
export interface FrameProps {
  /** The page: an .html file of the package, relative to its folder ("chart.html", "pages/meter.html"). */
  src: string;
  /** What it shows, in words: its accessible name, and what stands in for it where pixels aren't drawn. */
  label: string;
  /** Its height in pixels; without one it fills the space it is given. */
  height?: number;
  /** Data for the page, as plain values (256 KB at most): `cmd.data` there, and `cmd.on("data", fn)` on each change. */
  data?: WireValue | null;
  /** The page sent a value (`cmd.post(value)`). Not a press: it can't start an act. */
  onMessage?: (value: WireValue) => void;
}
/**
 * Pixels of the widget's own inside its window: a page of the package (an .html file) drawn in a sandboxed frame, for a canvas, a chart or a player the elements don't draw. The page's `cmd` is the widget's (`@cmd/widget-api/frame`), its data comes from `data` and its messages go to `onMessage`. Several may share a window. Where pixels aren't drawn (a preview, the phone) its label stands in.
 * @since 1.2
 */
export const Frame = el<FrameProps>("Frame");

/** Adapt's props. @since 1.3 */
export interface AdaptProps {
  /**
   * Cases, the most demanding first; a Case without conditions last, as the fallback (without one, nothing is drawn while none fits).
   */
  children?: ReactNode;
}
/**
 * A layout per size: draws the first Case its own box fits (its width and height in px, a Pane's when it sits in one), switched by cmd as the window resizes, without a round-trip to the widget. For a widget with a small and a large face; `Hide below` is enough to drop one thing from a narrow window, and `useSize()` is for numbers in logic (how many rows fit). Only the Case drawn is mounted: a field's draft in it is lost when the case changes. Give it room to measure: directly in a View, a Pane or a growing Stack; a height condition needs a box whose height isn't its content's.
 * @since 1.3
 */
export const Adapt = el<AdaptProps>("Adapt");

/** Case's props. @since 1.3 */
export interface CaseProps {
  /** Drawn from this width up. */
  minWidth?: number;
  /** Drawn up to this width. */
  maxWidth?: number;
  /** Drawn from this height up. */
  minHeight?: number;
  /** Drawn up to this height. */
  maxHeight?: number;
  /** The layout. */
  children?: ReactNode;
}
/**
 * One layout of an Adapt, drawn while the Adapt's box meets every condition given (each in px, inclusive); a Case without conditions always fits. Outside an Adapt it draws its children.
 * @since 1.3
 */
export const Case = el<CaseProps>("Case");

/** Dial's props. @since 1.3 */
export interface DialProps {
  /** The value, formatted ("12:30"). */
  value: string | number;
  /** Its steady name ("Time"): its accessible name, the value its description. */
  label: string;
  /** How much of the ring is drawn, 0–1 (default 0: only the track). */
  progress?: number;
  /** "accent" (default) while running, "needs" when done, "dim" paused or idle. */
  tone?: "accent" | "needs" | "dim";
  /** A quiet line under the value ("ends 14:32"). */
  caption?: string | number;
  /** A click on the value types a new one, sent to `onSubmit`. */
  editable?: boolean;
  /**
   * Return pressed in the typed value, with the text as typed ("10", "1:30", "90s": parse it). Escape or leaving sends nothing.
   */
  onSubmit?: (value: string) => void;
}
/**
 * A value to read across the room, in a ring that shows how much is left (a timer, a quota): as large as the view allows, so it goes alone in a View. With `editable`, a click on the value types a new one: Return sends it, Escape or leaving the field puts the value back.
 * @since 1.3
 */
export const Dial = el<DialProps>("Dial");

/** Picture's props. @since 1.3 */
export interface PictureProps {
  /**
   * data:image/png|jpeg|webp|gif;base64,… (at most 512 KB), or https://<a granted host>/… (cmd fetches it: at most 2 MB and 4096 px a side, kept an hour); null shows the placeholder. Never SVG.
   */
  src?: string | null;
  /** What it shows, in words (its accessible name; what stands in on a paired device that draws none). */
  alt: string;
  /** Fills its box, cropped (default), or fits inside it. */
  fit?: "cover" | "contain";
  /** Width over height (default 1: square). */
  ratio?: 1 | 1.333 | 1.5 | 1.778;
  /** Its width in px (default 64), or "fill": as large as the room left allows (a cover above a player). */
  size?: 24 | 32 | 44 | 64 | 96 | 128 | "fill";
  /** Its corners (default md). */
  radius?: "sm" | "md" | "none";
  /** An SF Symbol name. On the placeholder box (no src, loading, or failed), in the chart track colour. */
  icon?: string;
  /** Pressed. */
  onClick?: () => void;
}
/**
 * An image: a cover, a thumbnail, a logo. From a data: URL, or an https URL of a host in the package's net grant, which cmd fetches; never loaded by the page.
 * @since 1.3
 */
export const Picture = el<PictureProps>("Picture");

